{
  "name": "@yanu30adi/vision-bridge-mcp",
  "version": "0.1.2",
  "description": "MCP server that gives text-only coding agents (e.g. OpenCode + DeepSeek) the ability to see and analyze local images via the Gemini API.",
  "keywords": [
    "mcp",
    "model-context-protocol",
    "opencode",
    "gemini",
    "vision",
    "image-analysis",
    "ocr"
  ],
  "homepage": "https://github.com/yanuadin/vision-bridge-mcp#readme",
  "bugs": {
    "url": "https://github.com/yanuadin/vision-bridge-mcp/issues"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/yanuadin/vision-bridge-mcp.git"
  },
  "license": "MIT",
  "author": "yanuadin",
  "type": "module",
  "main": "src/index.js",
  "bin": {
    "vision-bridge-mcp": "src/index.js"
  },
  "directories": {
    "test": "test"
  },
  "files": [
    "src",
    "README.md",
    "LICENSE",
    ".env.example"
  ],
  "scripts": {
    "start": "node src/index.js",
    "test": "node --test",
    "lint": "eslint ."
  },
  "dependencies": {
    "@google/genai": "^2.0.0",
    "@modelcontextprotocol/sdk": "^1.0.0",
    "zod": "^3.23.8"
  },
  "devDependencies": {
    "eslint": "^9.9.0"
  },
  "engines": {
    "node": ">=18.0.0"
  }
}
